## 25. `overscroll-behavior` + Pull-To-Refresh Natív Implementáció

```javascript
// Natív iOS pull-to-refresh – UIRefreshControl egyenértékű
class NativePullToRefresh {
  constructor(scrollEl, onRefresh) {
    this.el = scrollEl;
    this.onRefresh = onRefresh;
    this.startY = 0;
    this.pulling = false;
    this.threshold = 72;
    this.indicator = this.createIndicator();
    this.bind();
  }

  createIndicator() {
    const el = document.createElement('div');
    el.style.cssText = `
      position: absolute; top: -48px; left: 50%; 
      transform: translateX(-50%) scale(0);
      width: 32px; height: 32px; 
      border-radius: 50%;
      background: var(--surface);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border: 0.5px solid var(--border);
      display: flex; align-items: center; justify-content: center;
      transition: transform 0.3s var(--spring-ios, cubic-bezier(0.34,1.4,0.64,1));
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    `;
    el.innerHTML = `<svg viewBox="0 0 24 24" width="16" height="16" fill="var(--fg3)">
      <path d="M12 6v3l4-4-4-4v3c-4.42 0-8 3.58-8 8 0 1.57.46 3.03 1.24 4.26L6.7 14.8A5.87 5.87 0 016 12c0-3.31 2.69-6 6-6zm6.76 1.74L17.3 9.2A5.87 5.87 0 0118 12c0 3.31-2.69 6-6 6v-3l-4 4 4 4v-3c4.42 0 8-3.58 8-8 0-1.57-.46-3.03-1.24-4.26z"/>
    </svg>`;
    this.el.style.position = 'relative';
    this.el.prepend(el);
    return el;
  }

  bind() {
    this.el.addEventListener('touchstart', e => {
      if (this.el.scrollTop === 0) {
        this.startY = e.touches[0].clientY;
        this.pulling = true;
      }
    }, { passive: true });

    this.el.addEventListener('touchmove', e => {
      if (!this.pulling) return;
      const dy = e.touches[0].clientY - this.startY;
      if (dy < 0) { this.pulling = false; return; }

      const progress = Math.min(dy / this.threshold, 1);
      const rubberDy = dy > this.threshold
        ? this.threshold + (dy - this.threshold) * 0.3
        : dy;

      this.indicator.style.transform = 
        `translateX(-50%) translateY(${rubberDy * 0.5}px) scale(${progress}) rotate(${progress * 180}deg)`;
      this.indicator.style.opacity = progress;
    }, { passive: true });

    this.el.addEventListener('touchend', async e => {
      if (!this.pulling) return;
      this.pulling = false;
      const dy = e.changedTouches[0].clientY - this.startY;

      if (dy >= this.threshold) {
        this.indicator.style.transform = 'translateX(-50%) translateY(24px) scale(1) rotate(360deg)';
        await this.onRefresh();
      }

      this.indicator.style.transform = 'translateX(-50%) scale(0)';
      this.indicator.style.opacity = '0';
    }, { passive: true });
  }
}

// Használat
const ptr = new NativePullToRefresh(
  document.getElementById('scroll-area'),
  async () => {
    // Új üzenetek betöltése
    await newChat();
  }
);
