## 2. JS PATCH – A legelső `<script>` blokk **elejére** (a `'use strict';` sor után)

```javascript
/* ═══════════════════════════════════════════
   NATIVE FEEL ENGINE v1.0
   ═══════════════════════════════════════════ */

// ── 1. HAPTICS – iOS Taptic Engine
const H = {
  light:     () => navigator.vibrate?.(8),
  medium:    () => navigator.vibrate?.(18),
  heavy:     () => navigator.vibrate?.(35),
  rigid:     () => navigator.vibrate?.([12, 4, 12]),
  success:   () => navigator.vibrate?.([8, 25, 8]),
  error:     () => navigator.vibrate?.([40, 25, 40]),
  selection: () => navigator.vibrate?.(4),
  warning:   () => navigator.vibrate?.([15, 10, 30]),
};

// ── 2. SPRING ANIMATE – Web Animations API compositor thread-en
function springAnim(el, from, to, opts = {}) {
  const { duration = 420, bounce = 'medium', onDone } = opts;
  const curves = {
    light:  'cubic-bezier(0.34,1.2,0.64,1)',
    medium: 'cubic-bezier(0.34,1.4,0.64,1)',
    heavy:  'cubic-bezier(0.34,1.7,0.64,1)',
  };
  const anim = el.animate(
    [from, to],
    { duration, easing: curves[bounce] ?? curves.medium, fill: 'forwards' }
  );
  anim.onfinish = () => { anim.commitStyles(); anim.cancel(); onDone?.(); };
  return anim;
}

// ── 3. TAP FEEDBACK – minden gombra egységesen
function tapFb(el, scale = 0.84) {
  springAnim(el,
    { transform: 'scale(1)' },
    { transform: `scale(${scale})` },
    { duration: 120, bounce: 'light' }
  );
  setTimeout(() => springAnim(el,
    { transform: `scale(${scale})` },
    { transform: 'scale(1)' },
    { duration: 380, bounce: 'heavy' }
  ), 110);
}

// ── 4. GLOBÁLIS TAP FEEDBACK regisztráció
document.addEventListener('pointerdown', e => {
  const target = e.target.closest(
    '.sbtn,.ibtn,.tact,.src-chip,.hcard-del,.sb-new,.sb-close,.ip-back,.ip-add,.ip-send,.ip-mbtn,.agent-toggle,.cb-copy,#stb,.apple-btn'
  );
  if (!target || target.disabled) return;
  H.selection();
}, { passive: true });

// ── 5. SCROLLEND – pontos scroll vég detektálás
const _sa = document.getElementById('scroll-area');
if (_sa) {
  _sa.addEventListener('scrollend', () => {
    const atBot = _sa.scrollHeight - _sa.scrollTop - _sa.clientHeight < 120;
    document.getElementById('stb')?.classList.toggle('show', !atBot);
  }, { passive: true });
}

// ── 6. SCHEDULER – prioritásos task ütemezés (ha elérhető)
const _sched = typeof scheduler !== 'undefined' ? scheduler : {
  postTask: (fn, { priority } = {}) =>
    priority === 'user-blocking'
      ? Promise.resolve().then(fn)
      : new Promise(r => setTimeout(() => { fn(); r(); }, 0))
};

// ── 7. VIEW TRANSITIONS wrapper
function withTransition(fn) {
  if (document.startViewTransition) {
    return document.startViewTransition(fn);
  }
  fn();
}

// ── 8. SIDEBAR – spring animáció View Transition-nel
const _origOpenSB  = typeof openSB  !== 'undefined' ? openSB  : null;
const _origCloseSB = typeof closeSB !== 'undefined' ? closeSB : null;

// openSB() és closeSB() felülírása a JS betöltése után:
window.addEventListener('load', () => {
  // Haptic a sidebar megnyitásakor
  document.getElementById('btn-sb-open')?.addEventListener('pointerdown', () => H.medium(), { passive: true });
  document.getElementById('btn-sb-close')?.addEventListener('pointerdown', () => H.light(), { passive: true });

  // Send gomb – erősebb haptic
  document.getElementById('sbtn')?.addEventListener('pointerdown', e => {
    if (!e.currentTarget.disabled) H.medium();
  }, { passive: true });

  // Hosszú nyomás – rigid haptic (natív iOS context menu feel)
  // (a longPressTimer callback-be illik, de itt adjuk hozzá a fogadó oldalán)
  document.getElementById('msg-list')?.addEventListener('contextmenu', e => {
    H.rigid();
  }, { passive: true });

  // History card törlés
  document.querySelectorAll('.hcard-del').forEach(btn => {
    btn.addEventListener('pointerdown', () => H.error(), { passive: true });
  });

  // FIELD-SIZING fallback – ha a böngésző még nem támogatja
  if (!CSS.supports('field-sizing', 'content')) {
    const ta = document.getElementById('ta');
    if (ta) {
      const grow = () => {
        ta.style.height = 'auto';
        ta.style.height = Math.min(ta.scrollHeight, 100) + 'px';
      };
      ta.addEventListener('input', grow);
    }
  }
}, { once: true });

// ── 9. SCROLL-TO-BOTTOM – spring animációval
function goBot(smooth = true) {
  const sa = document.getElementById('scroll-area');
  if (!sa) return;
  if (smooth && 'scrollBehavior' in document.documentElement.style) {
    sa.scrollTo({ top: sa.scrollHeight, behavior: 'smooth' });
  } else {
    sa.scrollTop = sa.scrollHeight;
  }
}

// ── 10. TOAST HAPTIC – minden toast típushoz
const _origShowToast = typeof showToast !== 'undefined' ? showToast : null;

// ── 11. POINTER EVENTS – sidebar drag pontosabb
(function setupSidebarPointerDrag() {
  const sb = document.getElementById('sidebar');
  if (!sb) return;
  let startX = 0, dragging = false;

  sb.addEventListener('pointerdown', e => {
    if (e.pointerType === 'touch' || e.pointerType === 'pen') {
      startX = e.clientX;
      dragging = true;
      sb.setPointerCapture?.(e.pointerId);
    }
  }, { passive: true });

  sb.addEventListener('pointermove', e => {
    if (!dragging) return;
    const dx = e.clientX - startX;
    if (dx < 0 && sb.classList.contains('open')) {
      const pct = Math.max(dx / sb.offsetWidth, -1) * 100;
      sb.style.transform = `translateX(${pct}%)`;
      sb.style.transition = 'none';
    }
  }, { passive: true });

  sb.addEventListener('pointerup', e => {
    if (!dragging) return;
    dragging = false;
    sb.style.transform = '';
    sb.style.transition = '';
    const dx = e.clientX - startX;
    if (dx < -60) {
      H.light();
      typeof closeSB === 'function' && closeSB();
    }
  }, { passive: true });
})();

// ── 12. INTERSECTION OBSERVER – üzenetek olvasottság + animáció
(function setupMsgObserver() {
  const sa = document.getElementById('scroll-area');
  if (!sa || !('IntersectionObserver' in window)) return;

  const obs = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting) {
        e.target.dataset.seen = '1';
        obs.unobserve(e.target);
      }
    });
  }, { root: sa, rootMargin: '0px', threshold: 0.1 });

  // Megfigyeljük az összes meglévő üzenetet
  document.querySelectorAll('.msg-group').forEach(g => obs.observe(g));

  // MutationObserver – új üzenetek automatikus figyelése
  new MutationObserver(muts => {
    muts.forEach(m => m.addedNodes.forEach(n => {
      if (n.classList?.contains('msg-group')) obs.observe(n);
    }));
  }).observe(document.getElementById('msg-list') ?? sa, { childList: true });
})();

// ── 13. NUMBER ANIMATE – stream közben szám animáció
function animateNumber(el, from, to, dur = 600) {
  const startTime = performance.now();
  const easeOut = t => 1 - Math.pow(1 - t, 3);
  const step = now => {
    const p = Math.min((now - startTime) / dur, 1);
    el.textContent = Math.round(from + (to - from) * easeOut(p)).toLocaleString('hu-HU');
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

// ── 14. DOCUMENT ADOPTED STYLESHEETS – runtime téma
if ('adoptedStyleSheets' in document) {
  const dynSheet = new CSSStyleSheet();
  document.adoptedStyleSheets = [...document.adoptedStyleSheets, dynSheet];
  window._dynSheet = dynSheet;
}

// ── 15. SYSTEM THEME CHANGE – View Transition-nel
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
  if (document.startViewTransition) {
    document.startViewTransition(() => {});
  }
});
